import hashlib
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent

OLD_TEXT = r"""\textbf{Scalability vs. Sample Size:}
We evaluated the computational scaling of the GAC pipeline as sample size $N$ increased from $500$ to $10{,}000$ (Table~\ref{tab:exp4_timing}, Fig.~\ref{fig:exp4_n}) across 5 canonical random seeds ($42, 101, 202, 303, 404$) on dedicated hardware using pure untraced wall-clock execution time (\texttt{time.perf\_counter()}). Peak process memory was recorded in a separate run via \texttt{tracemalloc}. In pure untraced execution, GAC executes in $0.736 \pm 0.089\text{ s}$ at $N=500$ and $0.835 \pm 0.030\text{ s}$ at $N=10{,}000$, yielding an empirical power-law exponent of $\beta = 0.09 \pm 0.17$ ($95\%$ bootstrap CI: $[-0.03, 0.24]$) across the entire range (and $\beta \approx 0.81$ over $N \in [500, 5{,}000]$ where runtime scales from $0.736\text{ s}$ to $4.760 \pm 1.607\text{ s}$). In comparison, Standard Consensus reaches $3.175 \pm 0.234\text{ s}$ at $N=10{,}000$, demonstrating a $3.80\times$ execution speedup for GAC. Standard Consensus requires $2.61\text{ GB}$ peak process memory at $N=10{,}000$ compared to $68.9\text{ MB}$ for GAC (a $97.4\%$ reduction). The timing jump at $N=8{,}000$ observed in an earlier run was not reproduced in the final runs (evaluated across 5 independent random seeds; full environmental telemetry logs are preserved in \texttt{results/timing\_rerun\_environment\_log.json}). Note that Table~\ref{tab:exp4_timing} evaluates benchmark data under $D=200$ and $K=3$, whereas Table~\ref{tab:exp5_controlled} Config~A evaluates $D=100$ and $K=5$; because the two experimental protocols differ in dimensionality $D$, cluster count $K$, and measurement mode, their respective timings reflect their distinct experimental settings. The bipartite graph compression reduces auxiliary consensus graph memory from $762.9\text{ MB}$ to $3.05\text{ MB}$ at $N=10{,}000$ (a \MemoryScalingTenKGraphReduction\ reduction, Table~\ref{tab:exp4_timing}; at $N=8{,}000$, graph memory drops from $488.3\text{ MB}$ to $2.44\text{ MB}$, a $99.5\%$ reduction). Separately, in peak process memory (measured via tracemalloc), GAC reduces memory footprint from $2{,}670.6\text{ MB}$ to $68.9\text{ MB}$ at $N=10{,}000$ (a \MemoryScalingTenKReduction\ reduction) and from $1{,}708.8\text{ MB}$ to $61.4\text{ MB}$ at $N=8{,}000$ (\MemoryScalingEightKReduction\ reduction). Multi-metric resource profiling (Fig.~\ref{fig:exp4_quad}) confirms that bipartite anchor consensus provides consistent acceleration across all sample scales while maintaining a compact memory footprint."""

NEW_TEXT = r"""\textbf{Scalability vs. Sample Size:}
We evaluated the computational scaling of the GAC pipeline as sample size $N$ increased from $500$ to $10{,}000$ (Table~\ref{tab:exp4_timing}, Fig.~\ref{fig:exp4_n}) across 5 canonical random seeds ($42, 101, 202, 303, 404$) on dedicated workstation hardware using pure untraced wall-clock execution time (\texttt{time.perf\_counter()}). Peak process memory was recorded in a separate run via \texttt{tracemalloc}. In pure untraced execution, GAC runtime scales monotonically from $0.836 \pm 0.096\text{ s}$ at $N=500$ to $4.354 \pm 1.252\text{ s}$ at $N=10{,}000$, yielding an empirical power-law exponent of $\beta = 0.548 \pm 0.013$ ($95\%$ seed-bootstrap CI: $[0.527, 0.568]$) across the evaluated range. In comparison, Standard Consensus runtime grows from $0.854 \pm 0.095\text{ s}$ at $N=500$ to $11.046 \pm 2.055\text{ s}$ at $N=10{,}000$ ($\beta = 0.851 \pm 0.010$, $95\%$ CI: $[0.834, 0.867]$), demonstrating a $2.54\times$ aggregate speedup (mean per-seed speedup $2.699 \pm 0.842\times$) for GAC at $N=10{,}000$. Standard Consensus requires $2.61\text{ GB}$ peak process memory at $N=10{,}000$ compared to $68.8\text{ MB}$ for GAC (a $97.4\%$ reduction). Reconciling this evaluation with the extreme-scale benchmark: Table~\ref{tab:exp4_timing} evaluates synthetic mixtures with $D=200$ and $K=3$ using pure untraced execution timing, whereas Table~\ref{tab:exp5_controlled} Config~A evaluates $D=100$ and $K=5$ with inline memory-tracing overhead (executing in $5.58 \pm 0.63\text{ s}$ at $N=10{,}000$); the respective timings reflect these distinct dimensionality, cluster count, and measurement mode settings. Bipartite graph compression reduces auxiliary consensus graph memory from $762.9\text{ MB}$ to $3.05\text{ MB}$ at $N=10{,}000$ (a \MemoryScalingTenKGraphReduction\ reduction, Table~\ref{tab:exp4_timing}; at $N=8{,}000$, graph memory drops from $488.3\text{ MB}$ to $2.44\text{ MB}$, a $99.5\%$ reduction). Separately, in peak process memory (measured via \texttt{tracemalloc}), GAC reduces memory footprint from $2{,}670.6\text{ MB}$ to $68.8\text{ MB}$ at $N=10{,}000$ (a \MemoryScalingTenKReduction\ reduction) and from $1{,}708.8\text{ MB}$ to $61.4\text{ MB}$ at $N=8{,}000$ (\MemoryScalingEightKReduction\ reduction). Multi-metric resource profiling (Fig.~\ref{fig:exp4_quad}) confirms that bipartite anchor consensus provides consistent acceleration across all sample scales while maintaining a compact memory footprint."""

OLD_CAPTION = r"""\caption{Empirical computational scaling and resource efficiency. (a) Pure untraced execution runtime as sample size $N$ increases from $500$ to $10{,}000$, yielding a fitted power-law exponent of $\beta = 0.09 \pm 0.17$ ($95\%$ bootstrap CI: $[-0.03, 0.24]$) across the full range ($\beta \approx 0.81$ over $N \in [500, 5{,}000]$) and a $3.80\times$ speedup over dense consensus at $N=10{,}000$ ($0.835\text{ s}$ vs. $3.175\text{ s}$). (b) Four-panel scaling analysis detailing wall-clock execution, empirical speedup acceleration factor, auxiliary consensus graph working memory, and peak dynamic RAM allocation.}"""

NEW_CAPTION = r"""\caption{Empirical computational scaling and resource efficiency. (a) Pure untraced execution runtime as sample size $N$ increases from $500$ to $10{,}000$, yielding a fitted power-law exponent of $\beta = 0.548 \pm 0.013$ ($95\%$ bootstrap CI: $[0.527, 0.568]$) and a $2.54\times$ speedup over dense consensus at $N=10{,}000$ ($4.354\text{ s}$ vs. $11.046\text{ s}$; per-seed speedup $2.699 \pm 0.842\times$). (b) Four-panel scaling analysis detailing wall-clock execution, empirical speedup acceleration factor, auxiliary consensus graph working memory, and peak dynamic RAM allocation.}"""

for rel_path in ["paper/main.tex", "springer_manuscript/main.tex"]:
    p = ROOT / rel_path
    c = p.read_text(encoding="utf-8")
    assert OLD_TEXT in c, f"OLD_TEXT not found in {rel_path}"
    assert OLD_CAPTION in c, f"OLD_CAPTION not found in {rel_path}"
    c = c.replace(OLD_TEXT, NEW_TEXT)
    c = c.replace(OLD_CAPTION, NEW_CAPTION)
    p.write_text(c, encoding="utf-8")
    print(f"Updated {rel_path}")

# Verify exact match
h1 = hashlib.md5((ROOT / "paper/main.tex").read_bytes()).hexdigest()
h2 = hashlib.md5((ROOT / "springer_manuscript/main.tex").read_bytes()).hexdigest()
assert h1 == h2, f"MD5 mismatch: {h1} vs {h2}"
print(f"Byte-for-byte identical verification PASSED (MD5: {h1})")
